__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"DB_VERSION",{enumerable:!0,get:function(){return T}}),Object.defineProperty(e,"SCHEMA_SQL",{enumerable:!0,get:function(){return n}});const T=15,n="\nCREATE TABLE IF NOT EXISTS settings (\n  key   TEXT PRIMARY KEY,\n  value TEXT\n);\n\n------------------------------------------------------------------\n-- M\xd3DULO 1 \xb7 ENTRENO (fuerza, rutina de 5 d\xedas)\n------------------------------------------------------------------\n\nCREATE TABLE IF NOT EXISTS routine_days (\n  id         TEXT PRIMARY KEY,\n  weekday    INTEGER NOT NULL UNIQUE,        -- 1 = lunes \u2026 5 = viernes\n  name       TEXT NOT NULL,                  -- \"Pull A\", \"Push B\", \u2026\n  focus      TEXT,                           -- \"Espalda \xb7 B\xedceps\"\n  active     INTEGER NOT NULL DEFAULT 1,     -- 0 = sin rutina ese d\xeda (descanso), v3\n  created_at TEXT NOT NULL DEFAULT (datetime('now')),\n  updated_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\nCREATE TABLE IF NOT EXISTS exercises (\n  id           TEXT PRIMARY KEY,\n  name         TEXT NOT NULL UNIQUE,\n  muscle_group TEXT,\n  is_custom    INTEGER NOT NULL DEFAULT 0,\n  created_at   TEXT NOT NULL DEFAULT (datetime('now')),\n  updated_at   TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\nCREATE TABLE IF NOT EXISTS routine_exercises (\n  id             TEXT PRIMARY KEY,\n  routine_day_id TEXT NOT NULL REFERENCES routine_days(id) ON DELETE CASCADE,\n  exercise_id    TEXT NOT NULL REFERENCES exercises(id) ON DELETE CASCADE,\n  position       INTEGER NOT NULL,\n  target_sets    INTEGER NOT NULL DEFAULT 3,\n  target_reps    TEXT NOT NULL DEFAULT '8-12',\n  created_at     TEXT NOT NULL DEFAULT (datetime('now')),\n  updated_at     TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\nCREATE INDEX IF NOT EXISTS idx_routine_exercises_day\n  ON routine_exercises(routine_day_id, position);\n\nCREATE TABLE IF NOT EXISTS workout_sessions (\n  id             TEXT PRIMARY KEY,\n  date           TEXT NOT NULL,              -- YYYY-MM-DD local\n  routine_day_id TEXT REFERENCES routine_days(id),\n  status         TEXT NOT NULL DEFAULT 'in_progress'\n                 CHECK (status IN ('in_progress','done','skipped')),\n  notes          TEXT,\n  created_at     TEXT NOT NULL DEFAULT (datetime('now')),\n  updated_at     TEXT NOT NULL DEFAULT (datetime('now')),\n  deleted_at     TEXT\n);\n\nCREATE INDEX IF NOT EXISTS idx_sessions_date ON workout_sessions(date);\n\nCREATE TABLE IF NOT EXISTS workout_sets (\n  id          TEXT PRIMARY KEY,\n  session_id  TEXT NOT NULL REFERENCES workout_sessions(id) ON DELETE CASCADE,\n  exercise_id TEXT NOT NULL REFERENCES exercises(id),\n  set_number  INTEGER NOT NULL,\n  reps        INTEGER NOT NULL,\n  weight_kg   REAL NOT NULL DEFAULT 0,\n  set_kind    TEXT NOT NULL DEFAULT 'normal',  -- normal | superset | dropset (v8)\n  rpe         REAL,                          -- esfuerzo percibido 1-10, opcional\n  created_at  TEXT NOT NULL DEFAULT (datetime('now')),\n  updated_at  TEXT NOT NULL DEFAULT (datetime('now')),\n  deleted_at  TEXT\n);\n\nCREATE INDEX IF NOT EXISTS idx_sets_session ON workout_sets(session_id);\nCREATE INDEX IF NOT EXISTS idx_sets_exercise ON workout_sets(exercise_id);\n\nCREATE TABLE IF NOT EXISTS body_weight_logs (\n  id         TEXT PRIMARY KEY,\n  date       TEXT NOT NULL UNIQUE,           -- un registro de peso por d\xeda\n  weight_kg  REAL NOT NULL,\n  created_at TEXT NOT NULL DEFAULT (datetime('now')),\n  updated_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\n------------------------------------------------------------------\n-- M\xd3DULO 2 \xb7 SKINCARE (checklists AM / PM)\n------------------------------------------------------------------\n\nCREATE TABLE IF NOT EXISTS skincare_steps (\n  id         TEXT PRIMARY KEY,\n  period     TEXT NOT NULL CHECK (period IN ('AM','PM')),\n  name       TEXT NOT NULL,\n  product    TEXT,                           -- \"Lipikar Baume\", \"Sakura Koji Wash\"\u2026\n  position   INTEGER NOT NULL DEFAULT 0,\n  active     INTEGER NOT NULL DEFAULT 1,     -- pasos desactivables sin perder hist\xf3rico\n  created_at TEXT NOT NULL DEFAULT (datetime('now')),\n  updated_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\nCREATE TABLE IF NOT EXISTS skincare_logs (\n  id           TEXT PRIMARY KEY,\n  date         TEXT NOT NULL,                -- YYYY-MM-DD local\n  step_id      TEXT NOT NULL REFERENCES skincare_steps(id) ON DELETE CASCADE,\n  completed_at TEXT NOT NULL DEFAULT (datetime('now')),\n  deleted_at   TEXT,                          -- borrado l\xf3gico (sync-ready, v2)\n  UNIQUE (date, step_id)\n);\n\nCREATE INDEX IF NOT EXISTS idx_skincare_logs_date ON skincare_logs(date);\n\n------------------------------------------------------------------\n-- M\xd3DULO 3 \xb7 NUTRICI\xd3N (kcal + macros, super\xe1vit)\n------------------------------------------------------------------\n\n-- \"A\xf1adido r\xe1pido\": comidas repetitivas con macros predefinidos\nCREATE TABLE IF NOT EXISTS quick_foods (\n  id          TEXT PRIMARY KEY,\n  name        TEXT NOT NULL,\n  kcal        REAL NOT NULL,\n  protein_g   REAL NOT NULL DEFAULT 0,\n  carbs_g     REAL NOT NULL DEFAULT 0,\n  fat_g       REAL NOT NULL DEFAULT 0,\n  is_favorite INTEGER NOT NULL DEFAULT 0,\n  created_at  TEXT NOT NULL DEFAULT (datetime('now')),\n  updated_at  TEXT NOT NULL DEFAULT (datetime('now')),\n  deleted_at  TEXT\n);\n\n-- Entradas del diario. Los macros se COPIAN del quick_food en el momento de\n-- registrar (snapshot): editar un alimento despu\xe9s no reescribe el hist\xf3rico.\nCREATE TABLE IF NOT EXISTS meal_entries (\n  id            TEXT PRIMARY KEY,\n  date          TEXT NOT NULL,               -- YYYY-MM-DD local\n  meal          TEXT NOT NULL DEFAULT 'other'\n                CHECK (meal IN ('breakfast','lunch','dinner','snack','other')),\n  quick_food_id TEXT REFERENCES quick_foods(id) ON DELETE SET NULL,\n  name          TEXT NOT NULL,\n  servings      REAL NOT NULL DEFAULT 1,\n  kcal          REAL NOT NULL,\n  protein_g     REAL NOT NULL DEFAULT 0,\n  carbs_g       REAL NOT NULL DEFAULT 0,\n  fat_g         REAL NOT NULL DEFAULT 0,\n  digestion     TEXT,                          -- 'heavy' | 'ok' | 'bloated' (v11)\n  created_at    TEXT NOT NULL DEFAULT (datetime('now')),\n  updated_at    TEXT NOT NULL DEFAULT (datetime('now')),\n  deleted_at    TEXT\n);\n\nCREATE INDEX IF NOT EXISTS idx_meals_date ON meal_entries(date);\n\n-- Objetivos con vigencia: el objetivo activo en una fecha es el \xfaltimo\n-- cuyo effective_from sea <= esa fecha (permite recalcular super\xe1vit por fases).\nCREATE TABLE IF NOT EXISTS nutrition_goals (\n  id             TEXT PRIMARY KEY,\n  effective_from TEXT NOT NULL,              -- YYYY-MM-DD\n  kcal           INTEGER NOT NULL,\n  protein_g      INTEGER NOT NULL,\n  carbs_g        INTEGER NOT NULL,\n  fat_g          INTEGER NOT NULL,\n  created_at     TEXT NOT NULL DEFAULT (datetime('now')),\n  updated_at     TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\nCREATE INDEX IF NOT EXISTS idx_goals_from ON nutrition_goals(effective_from);\n\n------------------------------------------------------------------\n-- M\xd3DULO 4 \xb7 HIDRATACI\xd3N (vasos de agua por d\xeda) \xb7 v4\n------------------------------------------------------------------\n\n-- Un registro acumulativo por fecha (vaso \u2248 250 ml). El objetivo diario vive\n-- en settings ('water_goal_glasses'). Beber agua cuenta como actividad del d\xeda.\nCREATE TABLE IF NOT EXISTS water_logs (\n  id         TEXT PRIMARY KEY,\n  date       TEXT NOT NULL UNIQUE,           -- YYYY-MM-DD local\n  glasses    INTEGER NOT NULL DEFAULT 0,\n  created_at TEXT NOT NULL DEFAULT (datetime('now')),\n  updated_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\nCREATE INDEX IF NOT EXISTS idx_water_date ON water_logs(date);\n\n--------------------------------------------------------------------\n-- M\xd3DULO 5 \xb7 PROGRESO (medidas corporales + fotos antes/despu\xe9s) \xb7 v6\n------------------------------------------------------------------\n\nCREATE TABLE IF NOT EXISTS body_measurements (\n  id         TEXT PRIMARY KEY,\n  date       TEXT NOT NULL,\n  kind       TEXT NOT NULL,\n  value_cm   REAL NOT NULL,\n  created_at TEXT NOT NULL DEFAULT (datetime('now')),\n  updated_at TEXT NOT NULL DEFAULT (datetime('now')),\n  deleted_at TEXT,\n  UNIQUE (date, kind)\n);\n\nCREATE INDEX IF NOT EXISTS idx_measure_date ON body_measurements(date);\nCREATE INDEX IF NOT EXISTS idx_measure_kind ON body_measurements(kind);\n\nCREATE TABLE IF NOT EXISTS progress_photos (\n  id         TEXT PRIMARY KEY,\n  date       TEXT NOT NULL,\n  uri        TEXT NOT NULL,\n  note       TEXT,\n  created_at TEXT NOT NULL DEFAULT (datetime('now')),\n  deleted_at TEXT\n);\n\nCREATE INDEX IF NOT EXISTS idx_photo_date ON progress_photos(date);\n\n------------------------------------------------------------------\n-- M\xd3DULO 6 \xb7 BIENESTAR (\xe1nimo + sue\xf1o por d\xeda) \xb7 v7\n------------------------------------------------------------------\n\nCREATE TABLE IF NOT EXISTS daily_wellness (\n  id          TEXT PRIMARY KEY,\n  date        TEXT NOT NULL UNIQUE,\n  mood        INTEGER,\n  sleep_hours REAL,\n  created_at  TEXT NOT NULL DEFAULT (datetime('now')),\n  updated_at  TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\nCREATE INDEX IF NOT EXISTS idx_wellness_date ON daily_wellness(date);\n\n------------------------------------------------------------------\n-- M\xd3DULO 7 \xb7 MENTE (enfoque, reflexi\xf3n estoica, h\xe1bitos) \xb7 v9\n------------------------------------------------------------------\n\nCREATE TABLE IF NOT EXISTS habits (\n  id         TEXT PRIMARY KEY,\n  name       TEXT NOT NULL,\n  icon       TEXT,\n  accent     TEXT,\n  position   INTEGER NOT NULL DEFAULT 0,\n  active      INTEGER NOT NULL DEFAULT 1,\n  created_at TEXT NOT NULL DEFAULT (datetime('now')),\n  updated_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\nCREATE TABLE IF NOT EXISTS habit_logs (\n  id         TEXT PRIMARY KEY,\n  habit_id   TEXT NOT NULL REFERENCES habits(id) ON DELETE CASCADE,\n  date       TEXT NOT NULL,\n  created_at TEXT NOT NULL DEFAULT (datetime('now')),\n  UNIQUE (habit_id, date)\n);\n\nCREATE INDEX IF NOT EXISTS idx_habit_logs_date ON habit_logs(date);\n\nCREATE TABLE IF NOT EXISTS journal_entries (\n  id         TEXT PRIMARY KEY,\n  date       TEXT NOT NULL,\n  period     TEXT NOT NULL CHECK (period IN ('AM','PM')),\n  content    TEXT,\n  created_at TEXT NOT NULL DEFAULT (datetime('now')),\n  updated_at TEXT NOT NULL DEFAULT (datetime('now')),\n  UNIQUE (date, period)\n);\n\nCREATE TABLE IF NOT EXISTS focus_sessions (\n  id         TEXT PRIMARY KEY,\n  date       TEXT NOT NULL,\n  minutes    INTEGER NOT NULL,\n  completed  INTEGER NOT NULL DEFAULT 0,\n  created_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\n\nCREATE INDEX IF NOT EXISTS idx_focus_date ON focus_sessions(date);\n\n------------------------------------------------------------------\n-- M\xd3DULO \xb7 CEREBRO DE BRASA (memoria a largo plazo del coach)\n------------------------------------------------------------------\n\nCREATE TABLE IF NOT EXISTS brasa_memory (\n  id         TEXT PRIMARY KEY,\n  kind       TEXT NOT NULL DEFAULT 'nota',     -- principio | lesion | preferencia | objetivo | hito | nota\n  text       TEXT NOT NULL,\n  tags       TEXT,                             -- csv de etiquetas\n  pinned     INTEGER NOT NULL DEFAULT 0,\n  source     TEXT NOT NULL DEFAULT 'user',     -- user | brasa\n  created_at TEXT NOT NULL DEFAULT (datetime('now')),\n  updated_at TEXT NOT NULL DEFAULT (datetime('now')),\n  deleted_at TEXT\n);\nCREATE INDEX IF NOT EXISTS idx_memory_kind ON brasa_memory(kind);\n\n------------------------------------------------------------------\n-- M\xd3DULO 8 \xb7 CAFE\xcdNA + RECUPERACI\xd3N \xb7 v10\n------------------------------------------------------------------\n\nCREATE TABLE IF NOT EXISTS caffeine_logs (\n  id         TEXT PRIMARY KEY,\n  ts         TEXT NOT NULL,                  -- instante de consumo (ISO)\n  date       TEXT NOT NULL,                  -- YYYY-MM-DD local\n  mg         INTEGER NOT NULL,\n  label      TEXT,\n  created_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\nCREATE INDEX IF NOT EXISTS idx_caffeine_date ON caffeine_logs(date);\n\nCREATE TABLE IF NOT EXISTS recovery_logs (\n  id         TEXT PRIMARY KEY,\n  date       TEXT NOT NULL,                  -- YYYY-MM-DD local\n  kind       TEXT NOT NULL,                  -- sauna | cold | mobility\n  minutes    INTEGER NOT NULL,\n  created_at TEXT NOT NULL DEFAULT (datetime('now'))\n);\nCREATE INDEX IF NOT EXISTS idx_recovery_date ON recovery_logs(date);\n\n------------------------------------------------------------------\n-- M\xd3DULO \xb7 RECORDATORIOS PERSONALIZADOS \xb7 v13\n------------------------------------------------------------------\n\nCREATE TABLE IF NOT EXISTS custom_reminders (\n  id            TEXT PRIMARY KEY,\n  title         TEXT NOT NULL,\n  body          TEXT,\n  icon          TEXT NOT NULL DEFAULT 'alarm-outline',\n  kind          TEXT NOT NULL DEFAULT 'daily',   -- interval | daily | weekly\n  every_minutes INTEGER NOT NULL DEFAULT 480,    -- solo kind=interval\n  start_hour    INTEGER NOT NULL DEFAULT 8,\n  start_minute  INTEGER NOT NULL DEFAULT 0,\n  weekdays      TEXT,                            -- solo kind=weekly, csv 1-7 (1=domingo)\n  quiet_from    INTEGER,                         -- franja de silencio (hora), NULL = sin silencio\n  quiet_to      INTEGER,\n  enabled       INTEGER NOT NULL DEFAULT 1,\n  created_at    TEXT NOT NULL DEFAULT (datetime('now')),\n  deleted_at    TEXT\n);\nCREATE INDEX IF NOT EXISTS idx_custom_reminders_enabled ON custom_reminders(enabled);\n\n------------------------------------------------------------------\n-- M\xd3DULO \xb7 AUTODIAGN\xd3STICO \xb7 v14\n------------------------------------------------------------------\n-- Fallos que ocurren por detr\xe1s y no se ven en pantalla, ca\xeddas y operaciones\n-- lentas. La columna clave es \xfanica para que un fallo repetido suba un contador\n-- en vez de crear una fila nueva cada vez. NO entra en la copia de seguridad:\n-- es estado del dispositivo, no datos del usuario.\n\nCREATE TABLE IF NOT EXISTS diagnostico (\n  id          INTEGER PRIMARY KEY AUTOINCREMENT,\n  clave       TEXT NOT NULL UNIQUE,           -- origen + mensaje normalizado\n  origen      TEXT NOT NULL,                  -- caida | nube | ia | datos | foto | aviso | red | lento | otro\n  gravedad    TEXT NOT NULL DEFAULT 'fallo',  -- fallo | aviso | lento\n  donde       TEXT NOT NULL,                  -- pantalla o funci\xf3n\n  mensaje     TEXT NOT NULL,                  -- ya limpio de datos personales\n  traza       TEXT,\n  duracion_ms INTEGER,                        -- solo cuando gravedad = 'lento'\n  veces       INTEGER NOT NULL DEFAULT 1,\n  primera_vez TEXT NOT NULL DEFAULT (datetime('now')),\n  ultima_vez  TEXT NOT NULL DEFAULT (datetime('now')),\n  version     TEXT NOT NULL DEFAULT '0',\n  plataforma  TEXT NOT NULL DEFAULT 'desconocida',\n  pantalla    TEXT,                           -- ruta activa al fallar\n  subido      INTEGER NOT NULL DEFAULT 0\n);\nCREATE INDEX IF NOT EXISTS idx_diagnostico_subido ON diagnostico(subido);\nCREATE INDEX IF NOT EXISTS idx_diagnostico_ultima ON diagnostico(ultima_vez);\n"},1480,[]);
